                { q: "ما اللفظ الدقيق الذي وصفت به ملابس وقمصان أهل النار بالآية 50 من سورة إبراهيم؟", os: ["سَرَابِيلُهُم مِّن قَطِرَانٍ وَتَغْشَىٰ وُجُوهَهُمُ النَّارُ", "ملابس من حديد", "ثياب من نار", "أغلال وسلاسل"], a: 0 },
                { q: "ما هو ختام الآية رقم 28 من سورة الرعد (الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ اللَّهِ...) وما الآية التالية لها؟", os: ["تليها الآية 29: (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ طُوبَىٰ لَهُمْ وَحُسْنُ مَآبٍ)", "تليها آية كذلك أرسلناك", "تليها ولو أن قرآناً سيرت به الجبال", "تليها والذين آتيناهم الكتاب"], a: 0 },
                { q: "كم آية تفصل بين قوله (أَفَمَن يَعْلَمُ أَنَّمَا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ الْحَقُّ) وقوله (وَالَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ) بالرعد؟", os: [" تفصل بينهما 5 آيات متتابعة في صفات أولي الألباب وعقبى الدار", "آيتان", "متتاليتان فوراً", "عشر آيات"], a: 0 },
                { q: "ما هو ختام الآية رقم 42 من سورة الرعد (وَقَدْ مَكَرَ الَّذِينَ مِن قَبْلِهِمْ فَلِلَّهِ الْمَكْرُ جَمِيعًا...)؟", os: ["يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍ ۗ وَسَيَعْلَمُ الْكُفَّارُ لِمَنْ عُقْبَى الدَّارِ", "وَاللَّهُ سَرِيعُ الْحِسَابِ", "إِنَّ رَبَّكَ شَدِيدُ الْعِقَابِ", "وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَيْءٍ مُّقْتَدِرًا"], a: 0 },
                { q: "ما هي الآية رقم 105 من سورة يوسف في الإعراض عن آيات السماوات والأرض؟", os: ["وَكَأَيِّن مِّن آيَةٍ فِي السَّمَاوَاتِ وَالْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ", "وَمَا يُؤْمِنُ أَكْثَرُهُم بِاللَّهِ إِلَّا وَهُم مُّشْرِكُونَ", "أَفَأَمِنُوا أَن تَأْتِيَهُمْ غَاشِيَةٌ", "قُلْ هَٰذِهِ سَبِيلِي"], a: 0 },
                { q: "ما الكلمة التي افتتحت بها الآية رقم 109 في ختام سورة يوسف عن إرسال الرجال؟", os: ["وَمَا أَرْسَلْنَا مِن قَبْلِك إِلَّا رِجَالًا نُّوحِي إِلَيْهِم مِّنْ أَهْلِ الْقُرَىٰ ۗ أَفَلَمْ يَسِيرُوا فِي الْأَرْضِ...", "حَتَّىٰ إِذَا اسْتَيْأَسَ الرُّسُلُ", "لَقَدْ كَانَ فِي قَصَصِهِمْ", "وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ"], a: 0 }
