// =========================================================================
// 🎛️ إدارة اختيار الأجزاء ديناميكياً بواسطة المستخدم
// =========================================================================

window.toggleJuzSelection = function(juzIndex) {
    const juzName = `الجزء ${juzIndex}`;
    const idx = window.selectedJuzList.indexOf(juzName);
    
    if (idx > -1) {
        if (window.selectedJuzList.length === 1) {
            alert("⚠️ يجب تحديد جزء واحد على الأقل للمشاركة في المسابقة!");
            return;
        }
        window.selectedJuzList.splice(idx, 1);
    } else {
        window.selectedJuzList.push(juzName);
    }
    window.renderJuzSelectorUI();
};

window.selectAllJuz = function() {
    window.selectedJuzList = [...window.quranJuzList];
    window.renderJuzSelectorUI();
};

window.clearJuzSelection = function() {
    window.selectedJuzList = ["الجزء 1"];
    window.renderJuzSelectorUI();
};

window.renderJuzSelectorUI = function() {
    const container = document.getElementById('juzSelectorGrid');
    if (!container) return;

    let html = `
    <div style="margin-bottom: 12px; display: flex; justify-content: space-between; align-items: center; direction: rtl;">
        <span style="font-size: 13px; color: var(--text); font-weight: bold;">حدد الأجزاء التي تحفظها وتود الاختبار فيها:</span>
        <div>
            <button onclick="window.selectAllJuz()" style="background: rgba(212,175,55,0.15); color: var(--gold); border: 1px solid var(--gold); padding: 4px 10px; border-radius: 6px; font-size: 11px; cursor: pointer; font-family:'Amiri', serif;">تحديد الكل (المصحف كامل)</button>
            <button onclick="window.clearJuzSelection()" style="background: transparent; color: var(--text2); border: 1px solid var(--border); padding: 4px 10px; border-radius: 6px; font-size: 11px; cursor: pointer; font-family:'Amiri', serif; margin-right: 5px;">إلغاء</button>
        </div>
    </div>
    <div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(85px, 1fr)); gap: 8px; direction: rtl;">
    `;

    for (let i = 1; i <= 30; i++) {
        const juzName = `الجزء ${i}`;
        const isSelected = window.selectedJuzList.includes(juzName);
        html += `
            <button onclick="window.toggleJuzSelection(${i})" style="background: ${isSelected ? 'var(--gold)' : 'var(--card)'}; color: ${isSelected ? '#111' : 'var(--text)'}; border: 1px solid ${isSelected ? 'var(--gold)' : 'var(--border)'}; padding: 8px 4px; border-radius: 8px; font-size: 12px; font-family: 'Amiri', serif; font-weight: bold; cursor: pointer; transition: 0.2s;">
                ${isSelected ? '✓ ' : ''}${juzName}
            </button>
        `;
    }

    html += `</div>`;
    container.innerHTML = html;
};

