// =========================================================================
// 🚀 دالة خلط وجمع الأسئلة من الأجزاء المختارة وتفعيل المحرك
// =========================================================================

window.startAcademyQuizEngine = function(category, level) {
    let pool = [];

    // جمع الأسئلة المطابقة من كل جزء اختاره المستخدم
    window.selectedJuzList.forEach(juzName => {
        if (window.quranJuzQuizzes[juzName] && 
            window.quranJuzQuizzes[juzName][category] && 
            window.quranJuzQuizzes[juzName][category][level]) {
            
            const qList = window.quranJuzQuizzes[juzName][category][level];
            qList.forEach(q => {
                pool.push({ ...q, juz: juzName });
            });
        }
    });

    if (pool.length === 0) {
        alert("⚠️ عذراً! لم نضف أسئلة لهذا المستوى في الأجزاء المختارة بعد. جرب اختيار الجزء الأول أو تغيير المستوى.");
        return;
    }

    // دالة التدوير والخلط العشوائي للأسئلة
    pool.sort(() => Math.random() - 0.5);

    // اختيار 15 سؤالاً كحد أقصى لكل اختبار
    const selectedQuestions = pool.slice(0, 15);

    window.currentActiveQuranQuiz = {
        category: category,
        level: level,
        juzRangeText: window.selectedJuzList.length === 30 ? "المصحف كاملًا" : window.selectedJuzList.join('، '),
        questions: selectedQuestions,
        answers: new Array(selectedQuestions.length).fill(null)
    };

    window.renderAcademyQuizQuestionsHTML();
};

window.renderAcademyQuizQuestionsHTML = function() {
    const container = document.getElementById('quranQuizzesContainer');
    const qData = window.currentActiveQuranQuiz;
    if (!container || !qData) return;

    let html = `
    <div class="comm-card" style="border-right: 4px solid var(--gold); direction: rtl; text-align: right; margin-bottom: 15px; background: var(--bg2); padding: 14px; border-radius: 12px;">
        <strong style="color: var(--gold); font-family: 'Amiri', serif; font-size: 16px;">📍 القسم: ${qData.category}</strong>
        <span style="display: block; font-size: 12px; color: var(--text2); margin-top: 4px;">🎯 الأجزاء المختارة: <strong style="color: var(--gold);">${qData.juzRangeText}</strong></span>
        <span style="display: block; font-size: 12px; color: var(--text2); margin-top: 2px;">المستوى الحالي: <span style="font-weight: bold; color: #ff4d4d;">${qData.level}</span> (إجمالي ${qData.questions.length} سؤالاً - شرط النجاح ${Math.ceil(qData.questions.length * 0.9)} من ${qData.questions.length})</span>
    </div>`;

    qData.questions.forEach((qItem, qIdx) => {
        html += `
        <div class="comm-card" style="margin-bottom: 14px; background: var(--card); border: 1px solid var(--border); padding: 14px; border-radius: 12px; direction: rtl; text-align: right;">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">
                <strong style="color: var(--text); font-size: 14px; line-height: 1.5;">س ${qIdx + 1}: ${qItem.q}</strong>
                <span style="font-size: 10px; background: rgba(212,175,55,0.1); color: var(--gold); padding: 2px 8px; border-radius: 10px; border: 1px solid var(--gold); font-family: 'Amiri', serif;">${qItem.juz}</span>
            </div>
            <div style="display: flex; flex-direction: column; gap: 8px;">
                ${qItem.os.map((option, oIdx) => {
                    const isSelected = qData.answers[qIdx] === oIdx;
                    return `
                    <label style="display: flex; align-items: center; gap: 8px; background: ${isSelected ? 'rgba(212,175,55,0.1)' : 'transparent'}; border: 1px solid ${isSelected ? 'var(--gold)' : 'var(--border)'}; padding: 10px 14px; border-radius: 8px; cursor: pointer; font-size: 13px; color: ${isSelected ? 'var(--gold)' : 'var(--text)'}; transition: 0.15s;">
                        <input type="radio" name="acad_q_${qIdx}" value="${oIdx}" ${isSelected ? 'checked' : ''} onchange="window.selectAcademyQuizAnswer(${qIdx}, ${oIdx})" style="accent-color: var(--gold);" />
                        ${option}
                    </label>`;
                }).join('')}
            </div>
        </div>`;
    });

    html += `
    <div style="display: flex; gap: 10px; margin-top: 20px; direction: rtl;">
        <button onclick="window.submitAcademyQuizResult()" style="flex: 1; background: var(--gold); color: #111; border: none; padding: 14px; border-radius: 12px; font-weight: bold; font-family: 'Amiri', serif; font-size: 15px; cursor: pointer; box-shadow: 0 4px 15px rgba(212,175,55,0.25);">📥 تصحيح المسابقة ومعاينة النتيجة الحية</button>
        <button onclick="window.renderQuranQuizzesDashboard()" style="background: transparent; border: 1px solid var(--border); color: var(--text2); padding: 14px 20px; border-radius: 12px; font-family: 'Amiri', serif; font-size: 14px; cursor: pointer;">انسحاب ورجوع ‹</button>
    </div>`;

    container.innerHTML = html;
    window.scrollTo({ top: 0, behavior: 'smooth' });
};

window.selectAcademyQuizAnswer = function(qIdx, oIdx) {
    if (window.currentActiveQuranQuiz) {
        window.currentActiveQuranQuiz.answers[qIdx] = oIdx;
    }
};

window.initAcademyQuizzesOnLoad = function() {
    if (document.getElementById('quranQuizzesContainer')) {
        window.renderQuranQuizzesDashboard();
    }
};

document.addEventListener('DOMContentLoaded', () => {
    window.initAcademyQuizzesOnLoad();
});
